from contextlib import contextmanager


@contextmanager
def opened(path):
    handle = open(path, encoding="utf-8")
    try:
        yield handle
    finally:
        handle.close()


def records(lines):
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        yield line


def temps(rows):
    for row in rows:
        kind, _, value = row.partition("=")
        if kind == "temp":
            yield int(value)


with opened("station.log") as handle:
    print(sum(temps(records(handle))))
